package com.zenbyte.leave.service;
import com.zenbyte.leave.entity.*; import com.zenbyte.leave.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class DashboardService {
 private final EmployeeRepository er; private final AttendanceService as; private final LeaveService ls; private final LeaveRequestRepository lr; private final HolidayRepository hr;
 public DashboardService(EmployeeRepository er,AttendanceService as,LeaveService ls,LeaveRequestRepository lr,HolidayRepository hr){this.er=er;this.as=as;this.ls=ls;this.lr=lr;this.hr=hr;}
 public Map<String,Object> admin(){LocalDate today=LocalDate.now();LocalDate first=today.withDayOfMonth(1);LocalDate last=first.plusMonths(1).minusDays(1);long total=er.findByActiveTrueOrderByNameAsc().size();long absent=as.absentCount(today);Map<String,Object> m=new LinkedHashMap<>();m.put("totalEmployees",total);m.put("todayAbsent",absent);m.put("todayPresent",Math.max(0,total-absent));m.put("currentMonthLeaveDays",er.findByActiveTrueOrderByNameAsc().stream().mapToInt(e->ls.applicableLeaveDaysForEmployee(e.getId(),first,last)).sum());m.put("attendance",Map.of("present",Math.max(0,total-absent),"absent",absent));List<Map<String,Object>> trend=new ArrayList<>();for(int i=5;i>=0;i--){YearMonth ym=YearMonth.from(today.minusMonths(i));LocalDate f=ym.atDay(1),t=ym.atEndOfMonth();trend.add(Map.of("month",ym.toString(),"days",er.findByActiveTrueOrderByNameAsc().stream().mapToInt(e->ls.applicableLeaveDaysForEmployee(e.getId(),f,t)).sum()));}m.put("leaveTrend",trend);m.put("pendingRequests",lr.findOverlapping(today.minusMonths(1),today.plusMonths(1)).stream().filter(x->x.getStatus()==LeaveStatus.PENDING).count());m.put("upcomingHolidays",hr.findByHolidayDateBetweenOrderByHolidayDateAsc(today,today.plusMonths(3)).stream().limit(5).map(h->Map.of("id",h.getId(),"date",h.getHolidayDate(),"name",h.getHolidayName())).toList());return m;}
 public Map<String,Object> user(Employee e){LocalDate today=LocalDate.now(),first=today.withDayOfMonth(1),last=first.plusMonths(1).minusDays(1);List<LeaveRequest> all=lr.findForEmployee(e.getId(),today.minusMonths(6),today.plusMonths(12));long approved=all.stream().filter(l->l.getStatus()==LeaveStatus.APPROVED).mapToInt(LeaveRequest::getLeaveDays).sum();long pending=all.stream().filter(l->l.getStatus()==LeaveStatus.PENDING).count();long rejected=all.stream().filter(l->l.getStatus()==LeaveStatus.REJECTED).count();Map<String,Object> m=new LinkedHashMap<>();m.put("employee",Map.of("id",e.getId(),"employeeId",e.getEmployeeId(),"name",e.getName(),"department",Objects.toString(e.getDepartment(),"")));m.put("approvedDays",approved);m.put("pendingRequests",pending);m.put("rejectedRequests",rejected);m.put("currentMonthLeaveDays",ls.applicableLeaveDaysForEmployee(e.getId(),first,last));m.put("recentLeaves",all.stream().limit(8).map(l->Map.of("id",l.getId(),"fromDate",l.getFromDate(),"toDate",l.getToDate(),"leaveDays",l.getLeaveDays(),"reason",l.getReason(),"status",l.getStatus())).toList()); List<Map<String,Object>> trend=new ArrayList<>(); for(int i=5;i>=0;i--){YearMonth ym=YearMonth.from(today.minusMonths(i));LocalDate f=ym.atDay(1),t=ym.atEndOfMonth();trend.add(Map.of("month",ym.toString(),"days",ls.applicableLeaveDaysForEmployee(e.getId(),f,t)));} m.put("leaveTrend",trend); return m;}
}
